"""Configuration loading and display for the minijinja command line clone."""
import ast
import os
import re


DEFAULTS = {
    "format": "auto", "autoescape": "auto", "include": True,
    "newline": True, "trim-blocks": False, "lstrip-blocks": False,
    "py-compat": False, "env": False, "strict": False,
    "safe-paths": [], "expr-out": "print", "fuel": 0,
    "syntax": {
        "block-start": "{%", "block-end": "%}",
        "variable-start": "{{", "variable-end": "}}",
        "comment-start": "{#", "comment-end": "#}",
        "line-statement-prefix": "", "line-comment-prefix": "",
    },
    "defines": {},
}

ENV_NAMES = {
    "format": "MINIJINJA_FORMAT", "autoescape": "MINIJINJA_AUTOESCAPE",
    "include": "MINIJINJA_INCLUDE", "newline": "MINIJINJA_NEWLINE",
    "trim-blocks": "MINIJINJA_TRIM_BLOCKS", "lstrip-blocks": "MINIJINJA_LSTRIP_BLOCKS",
    "py-compat": "MINIJINJA_PY_COMPAT", "env": "MINIJINJA_ENV",
    "strict": "MINIJINJA_STRICT", "safe-paths": "MINIJINJA_SAFE_PATH",
    "expr-out": "MINIJINJA_EXPR_OUT", "fuel": "MINIJINJA_FUEL",
}


def _toml_value(raw):
    raw = raw.strip()
    if raw.lower() in ("true", "false"):
        return raw.lower() == "true"
    try:
        return ast.literal_eval(raw)
    except (ValueError, SyntaxError):
        try:
            return int(raw.replace("_", ""))
        except ValueError:
            try:
                return float(raw.replace("_", ""))
            except ValueError:
                return raw.strip('"\'')


def _read_toml(path):
    result = {}
    current = result
    with open(path, encoding="utf-8") as f:
        for line in f:
            # Comments are ignored outside quoted strings.
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            m = re.fullmatch(r"\[([^]]+)\]", line)
            if m:
                current = result
                for part in m.group(1).split("."):
                    current = current.setdefault(part.strip(), {})
                continue
            if "=" not in line:
                continue
            key, val = line.split("=", 1)
            current[key.strip().strip('"')] = _toml_value(val)
    return result


def _bool(v):
    return str(v).lower() in ("true", "1", "yes", "on")


def load_config(config_file=None, environ=None):
    """Return settings merged as defaults, user TOML, then environment."""
    env = os.environ if environ is None else environ
    cfg = {k: (v.copy() if isinstance(v, (dict, list)) else v) for k, v in DEFAULTS.items()}
    cfg["syntax"] = DEFAULTS["syntax"].copy()
    cfg["defines"] = {}
    path = config_file or env.get("MINIJINJA_CONFIG_FILE")
    if path is None:
        path = os.path.join(env.get("HOME", os.path.expanduser("~")), ".minijinja.toml")
    if os.path.isfile(path):
        for key, value in _read_toml(path).items():
            if key == "syntax" and isinstance(value, dict):
                cfg["syntax"].update(value)
            elif key == "defines" and isinstance(value, dict):
                cfg["defines"].update(value)
            elif key in cfg:
                cfg[key] = value
    for key, name in ENV_NAMES.items():
        if name not in env:
            continue
        value = env[name]
        if key in ("include", "newline", "trim-blocks", "lstrip-blocks", "py-compat", "env", "strict"):
            cfg[key] = _bool(value)
        elif key == "safe-paths":
            cfg[key] = value.split(";" if os.name == "nt" else ":") if value else []
        elif key == "fuel":
            try:
                cfg[key] = int(value)

