"""Context data loading helpers for the minijinja CLI replica."""
import configparser
import json
import os
import pathlib
from urllib.parse import parse_qs


EXT_FORMAT = {
    ".json": "json", ".json5": "json", ".toml": "toml",
    ".ini": "ini", ".conf": "ini", ".config": "ini", ".properties": "ini",
    ".qs": "querystring", ".yaml": "yaml", ".yml": "yaml", ".cbor": "cbor",
}


def parse_define(expr):
    """Parse one -D expression into (name, value), raising ValueError if invalid."""
    if ":=" in expr:
        key, raw = expr.split(":=", 1)
        try:
            value = json.loads(raw)
        except Exception as e:
            raise ValueError(f"invalid JSON value for definition {key!r}: {e}")
    elif "=" in expr:
        key, value = expr.split("=", 1)
    else:
        key, value = expr, True
    if not key:
        raise ValueError("definition name cannot be empty")
    return key, value


def parse_ini(text):
    # MiniJinja uses `default` for entries before the first named section.
    p = configparser.ConfigParser(interpolation=None, strict=False)
    p.optionxform = str
    try:
        # ConfigParser cannot preserve keys before a named section if any exist.
        if any(line.strip().startswith("[") for line in text.splitlines()):
            pre, post = [], []
            section_seen = False
            for line in text.splitlines():
                if line.strip().startswith("["): section_seen = True
                (post if section_seen else pre).append(line)
            source = (("[default]\n" + "\n".join(pre) + "\n") if any("=" in x for x in pre) else "") + "\n".join(post)
        else: source = "[default]\n" + text
        p.read_string(source)
    except configparser.Error as e:
        raise ValueError(str(e))
    result = {}
    for section in p.sections():
        result[section] = dict(p.items(section, raw=True))
    return result


def parse_toml(text):
