#!/usr/bin/env python3
"""Command line front end for the MiniJinja-compatible renderer."""
import argparse
import json
import os
import re
import sys
import tempfile

from config import load_config, print_config
from context_data import load_context, parse_define
from expr import evaluate, repr_value, json_value, Undefined
from help_texts import SHORT_HELP, LONG_HELP, SYNTAX_HELP
from completion_texts import COMPLETIONS


def parser():
    p = argparse.ArgumentParser(prog="executable", description="minijinja-cli is a command line tool to render or evaluate jinja2 templates.", add_help=False)
    p.add_argument("-h", "--help", action="store_true")
    p.add_argument("-V", "--version", action="version", version="minijinja-cli 2.20.0")
    p.add_argument("template_file", nargs="?", default="-")
    p.add_argument("data_files", nargs="*")
    p.add_argument("--config-file")
    p.add_argument("-f", "--format", choices=["auto", "cbor", "ini", "json", "querystring", "toml", "yaml"])
    p.add_argument("-D", "--define", action="append", default=[])
    p.add_argument("-t", "--template")
    p.add_argument("-o", "--output", default="-")
    p.add_argument("--select")
    p.add_argument("--print-config", action="store_true")
    p.add_argument("-a", "--autoescape", choices=["auto", "html", "json", "none"])
    p.add_argument("--strict", action="store_true", default=None)
    p.add_argument("-n", "--no-newline", action="store_true", default=None)
    p.add_argument("--trim-blocks", action="store_true", default=None)
    p.add_argument("--lstrip-blocks", action="store_true", default=None)
    p.add_argument("--py-compat", action="store_true", default=None)
    p.add_argument("-s", "--syntax", action="append", default=[])
    p.add_argument("--env", action="store_true", default=None)
    p.add_argument("--no-include", action="store_true")
    p.add_argument("--safe-path", action="append", default=[])
    p.add_argument("--fuel", type=int)
    p.add_argument("-E", "--expr")
    p.add_argument("--expr-out", choices=["print", "json", "json-pretty", "status"])
    p.add_argument("--dump", choices=["instructions", "ast", "tokens"])
    p.add_argument("--repl", action="store_true")
    p.add_argument("--generate-completion", choices=["bash", "elvish", "fig", "fish", "nushell", "powershell", "zsh"])
    p.add_argument("--long-help", action="store_true")
    p.add_argument("--syntax-help", action="store_true")
    return p


def dump_tokens(template, syntax):
    """Produce the public token dump for the common lexer token forms."""
    vs, ve = syntax.get("variable-start", "{{"), syntax.get("variable-end", "}}")
    bs, be = syntax.get("block-start", "{%"), syntax.get("block-end", "%}")
    cs, ce = syntax.get("comment-start", "{#"), syntax.get("comment-end", "#}")
    pattern = re.compile("(" + "|".join(re.escape(a) + r".*?" + re.escape(b) for a,b in ((vs,ve),(bs,be),(cs,ce))) + ")", re.S)
    names = {"+":"Plus", "-":"Minus", "*":"Mul", "/":"Div", "//":"FloorDiv", "%":"Mod", "**":"Pow", "==":"Eq", "!=":"Ne", ">":"Gt", ">=":"Ge", "<":"Lt", "<=":"Le", "=":"Assign", "|":"Pipe", "~":"Tilde", "(":"ParenOpen", ")":"ParenClose", "[":"BracketOpen", "]":"BracketClose", "{":"BraceOpen", "}":"BraceClose", ",":"Comma", ".":"Dot", ":":"Colon"}
    lex = re.compile(r'\s+|(?:"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')|\d+(?:\.\d+)?|[A-Za-z_][\w]*|\*\*|//|==|!=|>=|<=|.', re.S)
    result=[]
    for part in pattern.split(template):
        if not part: continue
        if part.startswith(cs): continue
        if part.startswith(vs): left,right,open_name,close_name=vs,ve,"VariableStart","VariableEnd"
        elif part.startswith(bs): left,right,open_name,close_name=bs,be,"BlockStart","BlockEnd"
        else:
            result.append("TemplateData("+json.dumps(part,ensure_ascii=False)+")"); continue
        result.append(open_name)
        body=part[len(left):-len(right)]
        if body.startswith("-"): body=body[1:]
        if body.endswith("-"): body=body[:-1]
        for m in lex.finditer(body):
            word=m.group(0)
            if word.isspace(): continue
            if word[0] in "\"'":
                try: value=json.loads(word) if word[0]=='"' else word[1:-1].replace("\\'", "'")
                except Exception: value=word[1:-1]
                token_name = "String" if "\\" in word else "Str"
                result.append(token_name+"("+json.dumps(value,ensure_ascii=False)+")")
            elif word[0].isdigit(): result.append(("Float("+word+")") if "." in word else ("Int("+word+")"))
            elif word[0].isalpha() or word[0]=='_': result.append("Ident("+json.dumps(word)+")")
            else: result.append(names.get(word, "Unknown("+json.dumps(word)+")"))
        result.append(close_name)
    return "\n".join(result)+"\n"


def main(argv=None):
    args = parser().parse_args(argv)
    if args.help:
        sys.stdout.write(SHORT_HELP); return 0
    if args.long_help:
        sys.stdout.write(LONG_HELP)
        return 0
    if args.syntax_help:
        sys.stdout.write(SYNTAX_HELP)
        return 0
    cfg = load_config(args.config_file)
    # CLI settings override environment and config values.
    for key, value in (("format", args.format), ("autoescape", args.autoescape), ("expr-out", args.expr_out), ("fuel", args.fuel)):
        if value is not None: cfg[key] = value
    for key in ("strict", "trim-blocks", "lstrip-blocks", "py-compat", "env"):
        if getattr(args, key.replace('-', '_')) is True: cfg[key] = True
    if args.no_newline: cfg["newline"] = False
    if args.no_include: cfg["include"] = False
    if args.safe_path: cfg["safe-paths"].extend(args.safe_path)
    for item in args.syntax:
        if "=" not in item:
            print("error: syntax must be feature=value", file=sys.stderr); return 1
        key, value = item.split("=", 1)
        if key not in cfg["syntax"]:
            print(f"error: unknown syntax feature '{key}'", file=sys.stderr); return 1
        if not value:
            print("error: could not configure syntax\n\ncaused by: invalid custom delimiters", file=sys.stderr); return 1
        cfg["syntax"][key] = value
    cli_defs = args.define
    # Print config includes command line defines as the effective settings.
    for d in cli_defs:
        try:
            k, v = parse_define(d); cfg["defines"][k] = v
        except ValueError as e:
            print("error:", e, file=sys.stderr); return 1
    if args.print_config:
        sys.stdout.write(print_config(cfg)); return 0
    if args.generate_completion:
        sys.stdout.write(COMPLETIONS[args.generate_completion])
        return 0
    if args.template is not None and args.template_file not in ("-", ""):
        print("error: When --template is used, a template cannot be passed as argument (only an empty argument is allowed).", file=sys.stderr)
        return 1
    if args.template is None and args.template_file == "":
        print("error: Empty template names are only valid with --template.", file=sys.stderr)
        return 1
    # Only one of the template and data inputs may consume stdin.
    template_path = args.template_file
    if args.repl:
        template = ""
    elif args.expr is not None:
        # Expression evaluation has no template input. In particular, do not
        # consume stdin as a template when --expr is present.
        template = ""
    elif args.template is not None:
        template = args.template
    elif template_path == "-":
        if "-" in args.data_files:
            print("error: cannot read both template and data from stdin", file=sys.stderr); return 1
        template = sys.stdin.read()
    else:
        try:
            with open(template_path, encoding="utf-8") as f: template = f.read()
        except OSError as e:
            print("error:", e, file=sys.stderr); return 1
    data_stdin = None
    if "-" in args.data_files:
        if args.expr is None and args.template is None and template_path == "-":
            print("error: cannot read both template and data from stdin", file=sys.stderr); return 1
        data_stdin = sys.stdin.buffer.read() if cfg["format"] == "cbor" else sys.stdin.read()
    try:
        context = load_context(args.data_files, cfg["format"], (), args.select, data_stdin)
        context.update(cfg["defines"])
    except Exception as e:
        print("error:", e, file=sys.stderr); return 1
    if cfg["env"]: context["ENV"] = dict(os.environ)
    if args.repl:
        from renderer import render
        sys.stdout.write("MiniJinja Expression REPL\nType .help for help. Use .quit or ^D to exit.\n")
        while True:
            try: line = input(">>> ")
            except EOFError: break
            line = line.strip()
            if line in (".quit", ".exit"): break
            if line == ".help":
                sys.stdout.write("Commands:\n.quit / .exit  quit the REPL\n.help          shows this help\n.set x=expr    set variable x to the evaluated expression\n.unset x       unsets variable x\n.render tmpl   renders the given template source\n")
            elif line.startswith(".set "):
                assignment = line[5:]
                if "=" not in assignment: print("error: invalid command")
                else:
                    key, expr = assignment.split("=", 1)
                    try: context[key.strip()] = evaluate(expr, context, cfg["strict"], pycompat=cfg["py-compat"])
                    except Exception as e: print("error:", e)
            elif line.startswith(".unset "): context.pop(line[7:].strip(), None)
            elif line.startswith(".render "):
                try: print(render(line[8:], context, options=cfg))
                except Exception as e: print("error:", e)
            elif line.startswith("."): print("error: invalid command")
            elif not line: continue
            else:
                try:
                    value = evaluate(line, context, cfg["strict"], pycompat=cfg["py-compat"])
                    if not isinstance(value, Undefined):
                        print(json.dumps(value, ensure_ascii=False) if isinstance(value, str) else repr_value(value))
                except Exception as e: print("error:", e)
        return 0
    if args.dump == "tokens":
        out = dump_tokens(template, cfg["syntax"])
        if args.output == "-": sys.stdout.write(out)
        else:
            with open(args.output,"w",encoding="utf-8") as f: f.write(out)
        return 0
    esc = cfg["autoescape"]
    if esc == "auto":
        ext = os.path.splitext(template_path)[1].lower()
        esc = "html" if ext in (".html", ".htm", ".xml", ".xhtml", ".jinja.html") else "json" if ext in (".json", ".json5") else "none"
    if args.expr is not None:
        if cfg["fuel"] and cfg["fuel"] < 2:
            print(f"error: engine ran out of fuel (in {template_path}:1)", file=sys.stderr); return 1
        try: value = evaluate(args.expr, context, cfg["strict"], "none", cfg["py-compat"])
        except Exception as e:
            print("error:", e, file=sys.stderr); return 1
        mode = cfg["expr-out"]
        if mode == "status":
            if isinstance(value, bool): return int(value)
            if isinstance(value, int): return value & 255
            if isinstance(value, float):
                return int(value) & 255 if value.is_integer() else 0
            return int(not bool(value))
        if mode in ("json", "json-pretty"):
            try: out = json.dumps(json_value(value), ensure_ascii=False, indent=2 if mode == "json-pretty" else None, separators=None if mode == "json-pretty" else (",", ":"))
            except Exception as e:
                print("error:", e, file=sys.stderr); return 1
        else: out = repr_value(value)
    else:
